<?php
namespace Database\Seeders;
use App\Models\{Athlete,TrainingSession,TrainingType,User};
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder { public function run(): void {
 $admin=User::create(['name'=>'Coach Maria Villanueva','email'=>'admin@example.com','password'=>Hash::make('password'),'role'=>'admin']);
 $types=[];foreach([['Strength','Resistance and conditioning'],['Endurance','Aerobic capacity and stamina'],['Speed','Sprint mechanics and speed work'],['Recovery','Mobility and active recovery']] as [$name,$description])$types[] = TrainingType::create(['name'=>$name,'description'=>$description]);
 $people=[['Mikaela','Santos','Swimming','Cebu City'],['Paolo','Reyes','Basketball','Mandaue City'],['Rafael','Dizon','Track and Field','Lapu-Lapu City'],['Isabella','Garcia','Volleyball','Talisay City'],['Lorenzo','Bautista','Football','Cebu City'],['Angela','Flores','Swimming','Consolacion'],['Miguel','Castro','Track and Field','Minglanilla'],['Sofia','Ramos','Badminton','Cebu City'],['Enzo','Mendoza','Basketball','Naga City'],['Camille','Navarro','Volleyball','Mandaue City'],['Gabriel','Lim','Football','Cebu City']];$athletes=[];
 foreach($people as $i=>[$first,$last,$sport,$city]){ $user=null;if($i===0)$user=User::create(['name'=>"$first $last",'email'=>'athlete@example.com','password'=>Hash::make('password'),'role'=>'athlete']);$athletes[]=Athlete::create(['user_id'=>$user?->id,'athlete_id_number'=>sprintf('ATH-2026-%03d',$i+1),'first_name'=>$first,'last_name'=>$last,'birthdate'=>now()->subYears(17+$i%9)->subDays($i*27)->toDateString(),'sex'=>$i%2?'male':'female','sport'=>$sport,'team'=>'Cebu Performance Club','height_cm'=>160+$i*1.7,'weight_kg'=>52+$i*2.4,'address'=>"$city, Cebu, Philippines",'contact_number'=>sprintf('09%09d',123456780+$i),'emergency_contact_name'=>'Elena '.$last,'emergency_contact_number'=>sprintf('09%09d',223456780+$i)]); }
 for($i=0;$i<44;$i++){ $athlete=$athletes[$i%count($athletes)];$status=match($i%8){0,1,2,3=>'completed',4=>'scheduled',5=>'in_progress',6=>'missed',default=>'cancelled'};$date=now()->startOfDay()->addDays($i%8===4?1:-1*($i%30))->toDateString();TrainingSession::create(['athlete_id'=>$athlete->id,'training_type_id'=>$types[$i%4]->id,'created_by'=>$admin->id,'title'=>['Tempo intervals','Strength circuit','Sprint technique','Recovery mobility'][$i%4],'description'=>'Coach-led training block with warm-up, focused drills and cool-down.','session_date'=>$date,'start_time'=>sprintf('%02d:00:00',6+$i%11),'end_time'=>sprintf('%02d:00:00',7+$i%11),'location'=>'Cebu City Sports Center','intensity'=>['low','medium','high'][$i%3],'status'=>$status,'duration_minutes'=>$status==='completed'?35+$i%50:null,'perceived_exertion'=>$status==='completed'?4+$i%6:null,'distance_km'=>$status==='completed'?number_format(2.5+($i%10)*.7,2,'.',''):null,'athlete_notes'=>$status==='completed'?'Felt steady and finished the planned work.':null,'coach_feedback'=>$status==='completed'&&$i%2===0?'Good consistency. Keep your recovery between sets controlled.':null,'reviewed_by'=>$status==='completed'&&$i%2===0?$admin->id:null,'reviewed_at'=>$status==='completed'&&$i%2===0?now():null]); }
 } }
